    "takeaway": "Если «Капитан немо» — про персонажа, то эта заметка — про масштаб романа. Верн изобрёл techno-thriller за 100 лет до Тома Клэнси: это не фэнтези, а научно обоснованная фантастика, предсказавшая подводные лодки, акваланги и электрическое оружие."
