      "Анализ путинского стиля: прагматизм, терпение, использование слабостей оппонентов, ставка на суверенитет и невмешательство во внутренние дела.",
      "Киссинджер утверждает: демонизация Путина контрпродуктивна. Нужно понимать мотивы, чтобы предсказывать действия и находить точки соприкосновения.",
